import XCTest
import UIKit
import AVFoundation
@testable import MEFRION

@MainActor final class ReferenceTwinsTests:XCTestCase {
    func testAutomaticSpeciesDetectionAndBlankRejection() async throws {
        let engine=ReferenceTwinsEngine()
        for species in ["dog","cat"] {
            let assets=try await engine.assets(species:species)
            let image=try XCTUnwrap(assets.first.flatMap{engine.image($0)?.cgImage})
            let detected=try await PetSpeciesDetection.shared.detect(image)
            XCTAssertEqual(detected,species)
        }
        let blank=UIGraphicsImageRenderer(size:CGSize(width:320,height:320)).image {context in
            UIColor.white.setFill();context.fill(CGRect(x:0,y:0,width:320,height:320))
        }
        do {
            _=try await PetSpeciesDetection.shared.detect(try XCTUnwrap(blank.cgImage))
            XCTFail("A blank photo must not be assigned a pet species")
        } catch PetVisualError.species {}
    }
    func testPublicationRequiresDogOrCatInEveryPhoto() async throws {
        let engine=ReferenceTwinsEngine()
        for species in ["dog","cat"] {
            let assets=try await engine.assets(species:species)
            let image=try XCTUnwrap(assets.first.flatMap{engine.image($0)})
            let jpeg=try XCTUnwrap(image.jpegData(compressionQuality:0.85))
            try await PetPostValidator.shared.validatePhoto(jpeg)
        }
        let blank=UIGraphicsImageRenderer(size:CGSize(width:640,height:640)).image {context in
            UIColor.white.setFill();context.fill(CGRect(x:0,y:0,width:640,height:640))
        }
        let jpeg=try XCTUnwrap(blank.jpegData(compressionQuality:0.85))
        do {
            try await PetPostValidator.shared.validatePhoto(jpeg)
            XCTFail("A photo without a dog or cat must not be publishable")
        } catch PetPostValidationError.imageNotRecognized {}
    }
    func testVideoSamplingCoversEveryOneSecondAppearance() {
        let samples=PetPostValidator.sampleTimes(duration:300)
        XCTAssertEqual(samples.count,600)
        // Every one-second interval within the five-minute limit contains
        // at least one inspected frame, including non-integral start times.
        for tenth in 0..<2990 {
            let start=Double(tenth)/10
            XCTAssertTrue(samples.contains{$0>=start && $0<=start+1},"Missed interval starting at \(start)")
        }
    }
    func testVideoWithPetOnlyInMiddleSecondCanPost() async throws {
        let engine=ReferenceTwinsEngine()
        let assets=try await engine.assets(species:"dog")
        let dog=try XCTUnwrap(assets.first.flatMap{engine.image($0)})
        let file=try await makePublicationTestVideo(middle:dog)
        defer {try? FileManager.default.removeItem(at:file)}
        try await PetPostValidator.shared.validateVideo(file,duration:3)
    }
    func testVideoWithoutPetCannotPost() async throws {
        let file=try await makePublicationTestVideo(middle:nil)
        defer {try? FileManager.default.removeItem(at:file)}
        do {
            try await PetPostValidator.shared.validateVideo(file,duration:3)
            XCTFail("A video with no dog or cat must not be publishable")
        } catch PetPostValidationError.videoNotRecognized {}
    }
    private func makePublicationTestVideo(middle:UIImage?) async throws->URL {
        let output=FileManager.default.temporaryDirectory.appendingPathComponent(UUID().uuidString+".mp4")
        let writer=try AVAssetWriter(outputURL:output,fileType:.mp4)
        let input=AVAssetWriterInput(mediaType:.video,outputSettings:[
            AVVideoCodecKey:AVVideoCodecType.h264,
            AVVideoWidthKey:640,
            AVVideoHeightKey:480
        ])
        input.expectsMediaDataInRealTime=false
        let adaptor=AVAssetWriterInputPixelBufferAdaptor(assetWriterInput:input,sourcePixelBufferAttributes:[
            kCVPixelBufferPixelFormatTypeKey as String:kCVPixelFormatType_32ARGB,
            kCVPixelBufferWidthKey as String:640,
            kCVPixelBufferHeightKey as String:480
        ])
        writer.add(input)
        XCTAssertTrue(writer.startWriting())
        writer.startSession(atSourceTime:.zero)
        for second in 0..<3 {
            guard let pool=adaptor.pixelBufferPool else {throw PetPostValidationError.unreadable}
            var optional:CVPixelBuffer?
            guard CVPixelBufferPoolCreatePixelBuffer(kCFAllocatorDefault,pool,&optional)==kCVReturnSuccess,let buffer=optional else {throw PetPostValidationError.unreadable}
            CVPixelBufferLockBaseAddress(buffer,[])
            guard let context=CGContext(data:CVPixelBufferGetBaseAddress(buffer),width:640,height:480,bitsPerComponent:8,bytesPerRow:CVPixelBufferGetBytesPerRow(buffer),space:CGColorSpaceCreateDeviceRGB(),bitmapInfo:CGImageAlphaInfo.noneSkipFirst.rawValue) else {throw PetPostValidationError.unreadable}
            context.setFillColor(UIColor.white.cgColor);context.fill(CGRect(x:0,y:0,width:640,height:480))
            if second==1,let image=middle?.cgImage {context.draw(image,in:CGRect(x:0,y:0,width:640,height:480))}
            CVPixelBufferUnlockBaseAddress(buffer,[])
            let deadline=Date().addingTimeInterval(5)
            while !input.isReadyForMoreMediaData && Date()<deadline {try await Task.sleep(nanoseconds:10_000_000)}
            guard input.isReadyForMoreMediaData else {throw PetPostValidationError.unreadable}
            XCTAssertTrue(adaptor.append(buffer,withPresentationTime:CMTime(seconds:Double(second),preferredTimescale:600)))
        }
        input.markAsFinished()
        await withCheckedContinuation {continuation in writer.finishWriting {continuation.resume()} }
        XCTAssertEqual(writer.status,.completed)
        return output
    }
    func testSamePhotoFingerprintAcrossResize() async throws {
        let engine=ReferenceTwinsEngine();let dogs=try await engine.assets(species:"dog")
        let image=try XCTUnwrap(dogs.first.flatMap{engine.image($0)})
        let resized=UIGraphicsImageRenderer(size:CGSize(width:160,height:160)).image {_ in image.draw(in:CGRect(x:0,y:0,width:160,height:160))}
        let first=try XCTUnwrap(PetVisualFeature.fingerprint(try XCTUnwrap(image.cgImage)))
        let second=try XCTUnwrap(PetVisualFeature.fingerprint(try XCTUnwrap(resized.cgImage)))
        XCTAssertTrue(PetVisualFeature.samePhoto(first,second),"edges=\(zip(first.edges,second.edges).filter{$0 != $1}.count) mean=\(abs(first.mean-second.mean))")
        let reversed=PetVisualFeature.Fingerprint(edges:first.edges.map{!$0},mean:first.mean)
        XCTAssertFalse(PetVisualFeature.samePhoto(first,reversed))
    }
    func testCameraOrientationAndPixelLimit() throws {
        let raw=UIGraphicsImageRenderer(size:CGSize(width:3000,height:1500)).image{context in UIColor.orange.setFill();context.fill(CGRect(x:0,y:0,width:3000,height:1500))}
        let rotated=UIImage(cgImage:try XCTUnwrap(raw.cgImage),scale:1,orientation:.right)
        let normalized=try XCTUnwrap(rotated.normalizedForTwins())
        XCTAssertEqual(normalized.imageOrientation,.up)
        XCTAssertEqual(normalized.cgImage?.width,1024);XCTAssertEqual(normalized.cgImage?.height,2048)
    }
    func testCloudRankerFailurePropagationAndExactDuplicate() async throws {
        let engine=ReferenceTwinsEngine();let dogs=try await engine.assets(species:"dog")
        let sample=try XCTUnwrap(dogs.first);let image=try XCTUnwrap(engine.image(sample)?.cgImage)
        let ranker=VisionPetRanker()
        let result=try await ranker.rankStream(image:image,candidateIDs:[sample.id],species:"dog") {_ in image}
        XCTAssertTrue(result.isEmpty)
        do {_=try await ranker.rankStream(image:image,candidateIDs:[sample.id],species:"dog") {_ in throw URLError(.notConnectedToInternet)};XCTFail("A transport error must not become insufficient candidates")} catch {XCTAssertTrue(error is URLError)}
    }
    func testBundledReferenceIndexAndSelfExclusion() async throws {
        let engine=ReferenceTwinsEngine()
        let dogs=try await engine.assets(species:"dog"),cats=try await engine.assets(species:"cat")
        XCTAssertGreaterThan(dogs.count+cats.count,3000)
        XCTAssertTrue(dogs.allSatisfy{$0.species=="dog" && $0.demoOnly})
        XCTAssertTrue(cats.allSatisfy{$0.species=="cat" && $0.demoOnly})
        for species in ["dog","cat"] {
            let assets=species=="dog" ? dogs : cats
            let source=try XCTUnwrap(assets.first)
            let image=try XCTUnwrap(engine.image(source)?.cgImage)
            let result=try await engine.search(image:image,species:species)
            XCTAssertFalse(result.contains{$0.id==source.id},"The exact source image must not be returned")
            XCTAssertLessThanOrEqual(result.count,3)
            XCTAssertEqual(Set(result.map(\.id)).count,result.count)
            XCTAssertTrue(result.allSatisfy{$0.species==species})
        }
    }
    func testBlankInputAndMissingIndexAreFailures() async throws {
        let blank=UIGraphicsImageRenderer(size:CGSize(width:320,height:320)).image{context in UIColor.white.setFill();context.fill(CGRect(x:0,y:0,width:320,height:320))}
        do {_=try PetVisualFeature.extract(try XCTUnwrap(blank.cgImage),species:"dog");XCTFail("Blank photo must not return animal features")} catch {XCTAssertTrue(error is PetVisualError)}
        let engine=ReferenceTwinsEngine(root:FileManager.default.temporaryDirectory.appendingPathComponent(UUID().uuidString))
        do {_=try await engine.assets(species:"dog");XCTFail("Missing index is a system failure")} catch {}
    }
    func testReferenceHistoryOptInTTLAndErase() throws {
        let path=FileManager.default.temporaryDirectory.appendingPathComponent(UUID().uuidString+".json")
        defer {try? FileManager.default.removeItem(at:path)}
        let store=PrototypeStore(storageURL:path)
        XCTAssertTrue(store.referenceTwinsHistory.isEmpty)
        try store.saveReferenceSearch(owner:"owner-1",species:"cat",candidates:["pexels-7470"])
        XCTAssertEqual(PrototypeStore(storageURL:path).referenceTwinsHistory.first?.candidates,["pexels-7470"])
        let data=try Data(contentsOf:path);let json=try XCTUnwrap(JSONSerialization.jsonObject(with:data) as? [String:Any]);let history=try XCTUnwrap(json["referenceTwinsHistory"] as? [[String:Any]])
        XCTAssertNil(history.first?["image"]);XCTAssertNil(history.first?["features"])
        try store.persistMutation {store.referenceTwinsHistory.append(ReferenceSearchRecord(id:UUID(),owner:"owner-1",created:Date().addingTimeInterval(-90000),species:"dog",candidates:["pexels-616"]))}
        XCTAssertEqual(PrototypeStore(storageURL:path).referenceTwinsHistory.count,1)
        XCTAssertThrowsError(try store.saveReferenceSearch(owner:"",species:"dog",candidates:["pexels-616"]))
        try store.erasePrivateState();XCTAssertTrue(PrototypeStore(storageURL:path).referenceTwinsHistory.isEmpty)
    }
}


